WITH demo_yearly AS ( SELECT d.d_year, hd.hd_income_band_sk, hd.hd_buy_potential, SUM(sr.sr_return_amt_inc_tax) AS total_return_amount, COUNT(*) AS total_returns, AVG(sr.sr_return_amt_inc_tax) AS avg_return_amount FROM store_returns sr JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk JOIN customer c ON sr.sr_customer_sk = c.c_customer_sk WHERE d.d_year BETWEEN 2020 AND 2022 AND c.c_preferred_cust_flag = 'Y' GROUP BY d.d_year, hd.hd_income_band_sk, hd.hd_buy_potential ) SELECT d_year, hd_income_band_sk, hd_buy_potential, total_return_amount, total_returns, avg_return_amount, DENSE_RANK() OVER (PARTITION BY d_year ORDER BY total_return_amount DESC) AS demographic_year_rank, CASE WHEN total_return_amount > 10000 THEN 'Top Performer' WHEN total_return_amount > 5000 THEN 'Mid Performer' ELSE 'Low Performer' END AS performance_category, SUM(total_return_amount) OVER (PARTITION BY hd_income_band_sk ORDER BY d_year) AS cumulative_return_by_income FROM demo_yearly ORDER BY d_year, demographic_year_rank
